import Foundation

/// Decodes the bundled development catalog (generated by
/// `supabase/seed/build-seed.mjs`, identical IDs to `supabase/seed.sql`).
enum SeedCatalog {
    private struct File: Decodable {
        struct SeedWinery: Decodable {
            var id: UUID, name: String, country: String?, region: String?, founded: Int?, story: String?
            var practices: [String], highlights: [String]
        }
        struct SeedProfile: Decodable {
            var sweetness, acidity, body, tannin, fruitiness: Double
            var flavors: [String], notes: String, serve: [Int], decant: Int, aging: Int
        }
        struct SeedWine: Decodable {
            var id: UUID, productID: UUID, wineryID: UUID, name: String, type: WineType
            var country: String?, region: String?, appellation: String?, grapes: [String]
            var year: Int?, price: Double?, drinkFrom: Int?, drinkUntil: Int?
            var profile: SeedProfile, pairings: [String]
        }
        var wineries: [SeedWinery]
        var wines: [SeedWine]
    }

    static func load(bundle: Bundle = .main) -> [Wine] {
        guard let url = bundle.url(forResource: "SeedCatalog", withExtension: "json"),
              let data = try? Data(contentsOf: url),
              let file = try? JSONDecoder().decode(File.self, from: data) else { return [] }
        let wineries = Dictionary(uniqueKeysWithValues: file.wineries.map { w in
            (w.id, Winery(id: w.id, name: w.name, country: w.country, region: w.region, foundedYear: w.founded,
                          story: w.story, practices: w.practices, highlights: w.highlights, source: .editorial))
        })
        return file.wines.compactMap { s in
            guard let winery = wineries[s.wineryID] else { return nil }
            let p = s.profile
            let serve = p.serve.count == 2 ? p.serve[0]...p.serve[1] : nil
            return Wine(
                id: s.id, productID: s.productID, name: s.name, winery: winery, vintage: s.year, type: s.type,
                grapes: s.grapes.map { GrapeShare(name: $0) }, country: s.country, region: s.region,
                appellation: s.appellation, abv: nil, bottleSizeML: 750,
                price: s.price.map { Price(amount: Decimal($0), currency: "USD") },
                labelImagePath: nil, bottleImagePath: nil, drinkFrom: s.drinkFrom, drinkUntil: s.drinkUntil,
                characteristics: WineCharacteristics(
                    sweetness: p.sweetness, acidity: p.acidity, body: p.body, tannin: p.tannin, fruitiness: p.fruitiness,
                    flavors: p.flavors, tastingNotes: p.notes, servingTempC: serve,
                    decantMinutes: p.decant, agingPotentialYears: p.aging > 0 ? p.aging : nil, source: .editorial),
                pairings: s.pairings, factsSource: .editorial, communityRating: nil, ratingsCount: 0
            )
        }
    }
}
